    <h1>MapleSure SponsorConnect</h1>
    <form id="claim-form" onsubmit="handleSubmit(event)">
        <section aria-labelledby="lookup-section">
            <h2 id="lookup-section">Lookup Member</h2>
            <label for="policy-number">Policy Number</label>
            <input id="policy-number" name="policy-number" type="text" required aria-required="true" aria-label="Policy Number">

            <label for="member-id">Member ID</label>
            <input id="member-id" name="member-id" type="text" required aria-required="true" aria-label="Member ID">

            <button type="button" onclick="lookupMember()" aria-label="Look up member">Look up member</button>

            <div id="member-details" aria-live="polite"></div>
        </section>

        <section aria-labelledby="claim-section">
            <h2 id="claim-section">Claim Details</h2>
            <label for="last-day-worked">Last Day Worked</label>
            <input id="last-day-worked" name="last-day-worked" type="date" required aria-required="true" aria-label="Last Day Worked">

            <label for="first-day-absent">First Day Absent</label>
            <input id="first-day-absent" name="first-day-absent" type="date" required aria-required="true" aria-label="First Day Absent">

            <label for="nature-of-absence">Nature of Absence</label>
            <select id="nature-of-absence" name="nature-of-absence" required aria-required="true" aria-label="Nature of Absence">
                <option value="sick">Sick</option>
                <option value="injury">Injury</option>
                <option value="personal">Personal Leave</option>
            </select>

            <label for="details">Details</label>
            <textarea id="details" name="details" rows="4" aria-label="Details"></textarea>
        </section>

        <section aria-labelledby="upload-section">
            <h2 id="upload-section">Upload Documents</h2>
            <input id="documents" name="documents" type="file" multiple aria-label="Upload Documents" onchange="displayFileNames()">
            <ul id="file-list" aria-live="polite"></ul>
        </section>

        <button type="submit" aria-label="Submit Claim">Submit Claim</button>
    </form>

    <div id="confirmation" aria-live="assertive">
        <p>Reference Number: <span id="reference-number"></span></p>
        <p>Status: Received</p>
    </div>

    <footer class="footer">MapleSure Insurance — fictional demo application</footer>

    <script>
        var mockData = {
            "12345": {"name": "John Doe", "dob": "1980-05-15"},
            "67890": {"name": "Jane Smith", "dob": "1975-09-23"}
        };

        function lookupMember() {
            var memberId = document.getElementById('member-id').value;
            var memberDetailsDiv = document.getElementById('member-details');
            if (mockData[memberId]) {
                var member = mockData[memberId];
                memberDetailsDiv.innerHTML = 'Name: ' + member.name + '<br>Date of Birth: ' + member.dob;
            } else {
                memberDetailsDiv.innerHTML = 'Member not found.';
            }
        }

        function displayFileNames() {
            var input = document.getElementById('documents');
            var fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            Array.from(input.files).forEach(function(file) {
                var listItem = document.createElement('li');
                listItem.textContent = file.name;
                fileList.appendChild(listItem);
            });
        }

        function handleSubmit(event) {
            event.preventDefault();
            document.getElementById('claim-form').classList.add('hidden');
            document.getElementById('confirmation').style.display = 'block';
            var referenceNumber = 'MS-2026-08-' + Math.floor(1000 + Math.random() * 9000);
            document.getElementById('reference-number').textContent = referenceNumber;
        }
    </script>
</body>
</html>

